function computed(): Q[] {
  const qs: Q[] = [];
  // CURB-65 (generated vignettes)
  qs.push(...repeat(12, () => {
    const confused = Math.random() < 0.4, urea = pick([5.2, 6.5, 7.8, 9.4, 12]), rr = pick([18, 24, 31, 34]), sbp = pick([84, 96, 118, 135]), dbp = sbp < 90 ? 54 : pick([58, 66, 74]), age = pick([45, 58, 67, 74, 82]);
    const score = (confused ? 1 : 0) + (urea > 7 ? 1 : 0) + (rr >= 30 ? 1 : 0) + (sbp < 90 || dbp <= 60 ? 1 : 0) + (age >= 65 ? 1 : 0);
    const opts = [0, 1, 2, 3, 4, 5].filter((n) => n !== score).sort((a, b) => Math.abs(a - score) - Math.abs(b - score)).slice(0, 4).map(String);
    return mcq(S, "Respiratory", `A ${age}-year-old with community-acquired pneumonia is ${confused ? "newly confused" : "alert and orientated"}. Urea ${urea} mmol/L, respiratory rate ${rr}/min, BP ${sbp}/${dbp} mmHg. What is the CURB-65 score?`, String(score), opts,
      `Confusion ${confused ? 1 : 0}, urea >7 ${urea > 7 ? 1 : 0}, RR ≥30 ${rr >= 30 ? 1 : 0}, SBP <90 or DBP ≤60 ${sbp < 90 || dbp <= 60 ? 1 : 0}, age ≥65 ${age >= 65 ? 1 : 0}. Total ${score}: ${score <= 1 ? "consider home treatment" : score === 2 ? "consider hospital-based care" : "severe — hospital care, consider critical care"}.`, 2, 5);
  }));
  // Holliday–Segar maintenance fluids
  qs.push(...repeat(10, () => {
    const kg = pick([6, 8, 12, 15, 18, 22, 25, 30, 35, 40]);
    const ml = kg <= 10 ? kg * 100 : kg <= 20 ? 1000 + (kg - 10) * 50 : 1500 + (kg - 20) * 20;
    const wrong = [kg * 100, kg * 50 + 500, ml + 250, Math.round(ml * 0.8 / 10) * 10, kg * 4 * 24].filter((v) => v !== ml);
    return mcq(S, "Paediatrics", `Using the Holliday–Segar formula, what is the daily maintenance fluid requirement for a ${kg} kg child?`, `${ml.toLocaleString("en-GB")} mL/day`, [...new Set(wrong)].map((v) => `${v.toLocaleString("en-GB")} mL/day`),
      `100 mL/kg for the first 10 kg, 50 mL/kg for the next 10 kg, 20 mL/kg for each kg above 20 → ${ml.toLocaleString("en-GB")} mL/day.`, 2, 5);
  }));
  // Anion gap
  qs.push(...repeat(10, () => {
    const na = ri(132, 145), cl = ri(90, 110), hco3 = ri(8, 26);
    const ag = na - (cl + hco3);
    if (ag < 4) return null;
    return mcq(S, "Renal", `Na⁺ ${na} mmol/L, Cl⁻ ${cl} mmol/L, HCO₃⁻ ${hco3} mmol/L. What is the anion gap, and is it raised (reference roughly 8–16 mmol/L without potassium)?`, `${ag} mmol/L — ${ag > 16 ? "raised" : "normal"}`,
      [`${ag} mmol/L — ${ag > 16 ? "normal" : "raised"}`, `${na - cl} mmol/L — raised`, `${ag + hco3 - 5} mmol/L — raised`, `${Math.max(2, ag - 6)} mmol/L — normal`],
      `AG = Na − (Cl + HCO₃) = ${na} − ${cl + hco3} = ${ag}. Raised anion gap acidosis: e.g. DKA, lactic acidosis, renal failure, toxins.`, 2, 5);
  }));
  // BMI
  qs.push(...repeat(8, () => {
    const h = pick([1.55, 1.6, 1.65, 1.7, 1.75, 1.8]), w = ri(48, 120);
    const bmi = Math.round((w / (h * h)) * 10) / 10;
    const cat = bmi < 18.5 ? "Underweight" : bmi < 25 ? "Healthy weight" : bmi < 30 ? "Overweight" : bmi < 40 ? "Obese" : "Severely obese";
    const cats = ["Underweight", "Healthy weight", "Overweight", "Obese", "Severely obese"];
    return mcq(S, "Public health", `A patient weighs ${w} kg and is ${h} m tall. What is the BMI category (standard adult thresholds)?`, `${fmt(bmi)} kg/m² — ${cat}`, cats.filter((c) => c !== cat).map((c) => `${fmt(bmi)} kg/m² — ${c}`),
      `BMI = ${w} ÷ ${h}² = ${fmt(bmi)} kg/m². (Lower thresholds are used for some ethnic groups, e.g. South Asian, Chinese, Black African and Caribbean.)`, 1, 5);
  }));
  return qs;
}

export function plab(): Q[] {
  return [...ITEMS.map(([t, b, c, d, e]) => mcq(S, t, b, c, d, e, 2, 5)), ...computed()];
}
